/*
 * Focused regression harness for the _stats_create_group() error-path fix
 * (upstream eda99fc3839dcd439270ba5977ca6628bd9752cc).
 *
 * libdm-stats.c is included directly so its static _stats_create_group() and
 * _stats_group_destroy() are reachable. All remaining symbols come from the
 * libdevmapper built in the same worktree. dm_task_run() is linker-wrapped so
 * the positive path can make _stats_set_aux() succeed deterministically
 * without a real device-mapper device.
 *
 * Run: repro_stats_group negative   (unbound handle -> _stats_set_aux fails)
 *      repro_stats_group positive   (bound handle + wrapped run -> success)
 */
#include <stdio.h>
#include <string.h>

#include "libdm/libdm-stats.c"

int __wrap_dm_task_run(struct dm_task *dmt)
{
	(void) dmt;
	return 1;
}

static int setup(struct dm_stats **out_dms, struct dm_stats_region **out_regs,
		 struct dm_stats_group **out_groups, dm_bitset_t *out_bits)
{
	struct dm_stats *dms = dm_stats_create("stats-port-harness");
	struct dm_stats_region *regs;
	struct dm_stats_group *groups;
	dm_bitset_t bits;

	if (!dms) {
		fprintf(stderr, "dm_stats_create failed\n");
		return 0;
	}
	regs = dm_zalloc(sizeof(struct dm_stats_region));
	groups = dm_zalloc(sizeof(struct dm_stats_group));
	bits = dm_bitset_create(NULL, 1);
	if (!regs || !groups || !bits) {
		fprintf(stderr, "allocation failed\n");
		return 0;
	}
	regs[0].region_id = 0;
	regs[0].group_id = DM_STATS_GROUP_NOT_PRESENT;
	regs[0].aux_data = "";
	regs[0].timescale = NSEC_PER_MSEC;
	groups[0].group_id = DM_STATS_GROUP_NOT_PRESENT;
	groups[0].regions = NULL;
	groups[0].alias = NULL;
	groups[0].histogram = NULL;
	dm_bit_set(bits, 0);

	dms->max_region = 0;
	dms->nr_regions = 1;
	dms->regions = regs;
	dms->groups = groups;

	*out_dms = dms;
	*out_regs = regs;
	*out_groups = groups;
	*out_bits = bits;
	return 1;
}

int main(int argc, char **argv)
{
	struct dm_stats *dms;
	struct dm_stats_region *regs;
	struct dm_stats_group *groups;
	dm_bitset_t bits;
	uint64_t group_id = DM_STATS_GROUP_NOT_PRESENT;
	int positive = (argc > 1 && strcmp(argv[1], "positive") == 0);
	int r;

	if (!setup(&dms, &regs, &groups, &bits))
		return 2;

	/* Positive path: binding makes _set_stats_device() succeed and the
	 * wrapped dm_task_run() makes the @stats_set_aux message succeed. */
	if (positive) {
		dms->bind_major = 1;
		dms->bind_minor = 1;
	}

	r = _stats_create_group(dms, bits, "harness-alias", &group_id);
	printf("mode=%s _stats_create_group=%d group_id=%llu present=%d "
	       "regions=%p alias=%s\n",
	       positive ? "positive" : "negative", r,
	       (unsigned long long) group_id,
	       _stats_group_present(&groups[0]),
	       (void *) groups[0].regions,
	       groups[0].alias ? groups[0].alias : "(null)");

	if (positive) {
		if (r != 1) {
			fprintf(stderr, "FAIL: expected success return\n");
			return 1;
		}
		if (!_stats_group_present(&groups[0]) ||
		    groups[0].regions != bits || !groups[0].alias) {
			fprintf(stderr, "FAIL: group state not committed on success\n");
			return 1;
		}
		/* Success path: the group owns the bitmap/alias; teardown frees once. */
		_stats_group_destroy(&groups[0]);
	} else {
		if (r != 0) {
			fprintf(stderr, "FAIL: expected failure return\n");
			return 1;
		}
		/* This mirrors the public callers' bad: path. */
		dm_bitset_destroy(bits);
		/* Later handle teardown must not free the bitmap a second time. */
		_stats_group_destroy(&groups[0]);
	}

	/* Detach raw tables so dm_stats_destroy() does not walk them. */
	dms->regions = NULL;
	dms->groups = NULL;
	dms->max_region = DM_STATS_REGION_NOT_PRESENT;
	dms->nr_regions = DM_STATS_REGION_NOT_PRESENT;
	dm_stats_destroy(dms);
	dm_free(regs);
	dm_free(groups);
	printf("clean exit\n");
	return 0;
}

