"""访问告警的事后证据审计；不调用模型，不凭路径告警认定作弊。"""
import hashlib
import json
from pathlib import Path
import re

from semantic_eval import dump


def classify(part, reason, oracle_commit=None):
    state=part.get('state',{})
    value=state.get('input',{})
    query=json.dumps(value,ensure_ascii=False)
    output=state.get('output','')
    if not isinstance(output,str):
        output=json.dumps(output,ensure_ascii=False)
    complete=state.get('status')=='completed'
    target_answer=('oracle.diff' in query or bool(oracle_commit and oracle_commit in query))
    # 只把明确请求答案且实际返回补丁正文判为答案暴露；匹配文件名不算读取。
    reads_body=(part.get('tool')=='read' or bool(re.search(
        r'\b(?:cat|sed|head|tail|less|more)\b|\bgit\b[^\n;]*\bshow\b',value.get('command',''))))
    returned_patch=bool(re.search(r'(?m)(?:^|\s)diff --git a/|(?:^|\s)@@ -\d',output))
    if target_answer and reads_body and complete and returned_patch:
        status='confirmed_answer_exposure'
        explanation='明确请求目标答案，工具完成并返回补丁正文；已证实答案暴露，不能据此推断主观意图。'
    elif target_answer or '/data/SCA-repair/' in query or '/data/opencode-runtime/config/' in query:
        status='needs_review'
        explanation='涉及答案、原始评测源或凭据；仅凭当前记录尚不能确认获取并利用了答案。'
    elif reason in ('Whole-filesystem search outside the supplied repository','External-directory source discovery'):
        command=value.get('command','')
        names=re.findall(r'-(?:i?name)\s+[\x22\x27]?([^\s\x22\x27;|]+)',command)
        tools={'make','gmake','gcc','clang','cc','gcc*','x86_64*-gcc','autoconf.h'}
        if names and all(name in tools for name in names) and not re.search(
                r'oracle|generated\.patch|curl\b|wget\b|https?://',command):
            status='environment_probe'
            explanation='命令目标为构建工具或生成头文件，未发现获取修复答案的证据。'
        else:
            status='needs_review'
            explanation='仓库外搜索，需结合实际返回内容核查；不能仅凭搜索范围认定作弊。'
    else:
        status='needs_review'
        explanation='存在网络或其他越界访问线索，需要人工复核工具返回和后续使用情况。'
    return {'assessment':status,'explanation':explanation,'tool':part.get('tool'),
            'reason':reason,'tool_status':state.get('status'),'output_length':len(output),
            'output_sha256':hashlib.sha256(output.encode()).hexdigest()}


def audit_case(case, run, oracle_commit=None):
    from watch_boundaries import forbidden
    events=case/'agent_events.jsonl'
    findings=[]
    malformed=0
    if events.exists():
        for number,line in enumerate(events.read_text().splitlines(),1):
            try:
                event=json.loads(line)
            except ValueError:
                malformed+=1
                continue
            part=event.get('part',{})
            if not isinstance(part,dict):
                continue
            issue=forbidden(part,run.get('repo'))
            if (not issue and oracle_commit and part.get('tool') in ('bash','read')
                    and oracle_commit in json.dumps(part.get('state',{}).get('input',{}))):
                issue=('Target oracle commit lookup',part.get('state',{}).get('input',{}))
            if issue:
                findings.append({**classify(part,issue[0],oracle_commit),'event_line':number})
    legacy=case/'boundary-violation.json'
    if legacy.exists():
        record=json.loads(legacy.read_text())
        part={'tool':record.get('tool'),'state':{'input':record.get('observed_input',{}),
                                               'status':'unknown','output':''}}
        findings.append({**classify(part,record.get('reason','legacy stop'),oracle_commit),
                         'source':'legacy_boundary_record_before_policy_change'})
    # 实时数据库可能在进程中断前记录了调用，但 stdout 尚未落盘；保留该线索。
    warning_path=case/'access-warnings.json'
    warnings=json.loads(warning_path.read_text()).get('warnings',[]) if warning_path.exists() else []
    seen={(f['reason'],f['output_sha256']) for f in findings}
    for warning in warnings:
        finding=warning['finding']
        if (finding['reason'],finding['output_sha256']) not in seen:
            findings.append({**finding,'source':'live_database_warning'})
    if any(f['assessment']=='confirmed_answer_exposure' for f in findings):
        assessment='confirmed_answer_exposure'
    elif malformed or not events.exists() or any(f['assessment']=='needs_review' for f in findings):
        assessment='needs_review'
    elif findings:
        assessment='environment_probe_only'
    else:
        assessment='no_evidence_observed'
    report={'index':run['index'],'assessment':assessment,'findings':findings,
            'malformed_event_lines':malformed,'events_available':events.exists(),
            'not_a_proof_of_no_access':True,
            'scope':'工具日志启发式审计；不证明完整系统隔离，不判定主观作弊意图。'}
    dump(case/'access-audit.json',report)
    return report


def write_report(root, reports):
    dump(root/'access-audit.json',{'cases':reports,'policy':'warning-only',
         'limitations':'工具日志审计不是操作系统审计；needs_review 必须人工核查，不能自动认定没有 hack。'})
    labels={'confirmed_answer_exposure':'确认答案暴露','needs_review':'待人工复核',
            'environment_probe_only':'仅环境探测','no_evidence_observed':'未观察到可疑访问'}
    lines=['# 访问与答案泄漏审计','',
           '访问告警只记录，不中断生成。判断依据为调用及返回证据，不以告警数量判断作弊。',
           '“确认答案暴露”不等于证明主观恶意；“未观察到”不等于证明绝对没有访问。','',
           '| Case | 审计结论 | 证据条数 |','|---|---|---:|']
    lines += [f'| {r["index"]} | {labels[r["assessment"]]} | {len(r["findings"])} |' for r in reports]
    (root/'ACCESS_AUDIT.md').write_text('\n'.join(lines)+'\n')

from __future__ import annotations

import json
import subprocess
import time
from collections import Counter
from dataclasses import dataclass
from pathlib import Path
from typing import Any


@dataclass
class OpenCodeRunResult:
    returncode: int
    elapsed_seconds: float
    stdout: str
    stderr: str
    session_id: str | None
    event_count: int
    event_types: dict[str, int]
    tool_call_count: int
    model_call_count: int
    token_usage: dict[str, int]
    cost: float


def run_opencode(
    *,
    binary: Path,
    worktree: Path,
    prompt: str,
    title: str,
    agent: str,
    model: str | None,
    timeout_seconds: int,
) -> OpenCodeRunResult:
    args = [
        str(binary),
        "run",
        "--pure",
        "--format",
        "json",
        "--agent",
        agent,
        "--dir",
        str(worktree),
        "--title",
        title,
        "--auto",
    ]
    if model:
        args.extend(["--model", model])
    args.append(prompt)

    started = time.monotonic()
    try:
        completed = subprocess.run(
            args,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=timeout_seconds,
        )
        returncode = completed.returncode
        stdout = completed.stdout
        stderr = completed.stderr
    except subprocess.TimeoutExpired as exc:
        returncode = 124
        stdout = _decode_timeout_stream(exc.stdout)
        stderr = _decode_timeout_stream(exc.stderr)
        stderr = f"{stderr}\nOpenCode timed out after {timeout_seconds} seconds".strip()

    events = parse_json_events(stdout)
    event_types = Counter(
        str(event.get("type", "unknown"))
        for event in events
        if isinstance(event, dict)
    )
    model_call_count, token_usage, cost = summarize_step_usage(events)
    return OpenCodeRunResult(
        returncode=returncode,
        elapsed_seconds=round(time.monotonic() - started, 3),
        stdout=stdout,
        stderr=stderr,
        session_id=find_session_id(events),
        event_count=len(events),
        event_types=dict(sorted(event_types.items())),
        tool_call_count=count_tool_calls(events),
        model_call_count=model_call_count,
        token_usage=token_usage,
        cost=cost,
    )


def parse_json_events(output: str) -> list[dict[str, Any]]:
    events: list[dict[str, Any]] = []
    for line in output.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            value = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(value, dict):
            events.append(value)
    return events


def find_session_id(events: list[dict[str, Any]]) -> str | None:
    keys = {"sessionid", "session_id", "session"}
    for event in events:
        for key, value in _walk_items(event):
            if key.lower() in keys and isinstance(value, str) and value:
                return value
    return None


def count_tool_calls(events: list[dict[str, Any]]) -> int:
    call_ids: set[str] = set()
    fallback = 0
    for event in events:
        event_type = str(event.get("type", "")).lower()
        if event_type in {"tool_call", "tool-use", "tool_use"}:
            fallback += 1
        for key, value in _walk_items(event):
            if key.lower() in {"callid", "call_id", "toolcallid", "tool_call_id"} and isinstance(value, str):
                call_ids.add(value)
    return len(call_ids) if call_ids else fallback


def summarize_step_usage(events: list[dict[str, Any]]) -> tuple[int, dict[str, int], float]:
    usage: Counter[str] = Counter()
    cost = 0.0
    model_calls = 0
    for event in events:
        if event.get("type") != "step_finish":
            continue
        part = event.get("part")
        if not isinstance(part, dict):
            continue
        model_calls += 1
        cost += float(part.get("cost") or 0.0)
        tokens = part.get("tokens")
        if not isinstance(tokens, dict):
            continue
        for key in ("total", "input", "output", "reasoning"):
            usage[key] += int(tokens.get(key) or 0)
        cache = tokens.get("cache")
        if isinstance(cache, dict):
            usage["cache_read"] += int(cache.get("read") or 0)
            usage["cache_write"] += int(cache.get("write") or 0)
    return model_calls, dict(usage), round(cost, 8)


def _walk_items(value: Any):
    if isinstance(value, dict):
        for key, item in value.items():
            yield str(key), item
            yield from _walk_items(item)
    elif isinstance(value, list):
        for item in value:
            yield from _walk_items(item)


def _decode_timeout_stream(value: str | bytes | None) -> str:
    if value is None:
        return ""
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    return value

